constexpr int HM_WS[SCENE_COUNT] = {65, 65};
constexpr int HM_DS[SCENE_COUNT] = {65, 65};
constexpr float HM_ORIGIN_XS[SCENE_COUNT] = {-96.0F, -32.0F};
constexpr float HM_ORIGIN_ZS[SCENE_COUNT] = {-96.0F, -32.0F};
constexpr float HM_STEP_XS[SCENE_COUNT] = {3.0F, 1.0F};
constexpr float HM_STEP_ZS[SCENE_COUNT] = {3.0F, 1.0F};
inline const float* TERRAIN_HEIGHTS_TABLES[SCENE_COUNT] = {HM_0_HEIGHTS, HM_1_HEIGHTS};

/** Bilinear terrain height at world coordinates in a scene. The
 * game maps terrainHeightAt(x, z) to the active scene. */
inline float terrainHeightAtScene(int scene, float x, float z) {
  const float* hm = TERRAIN_HEIGHTS_TABLES[scene];
  const int hw = HM_WS[scene];
  const int hd = HM_DS[scene];
  float gx = (x - HM_ORIGIN_XS[scene]) / HM_STEP_XS[scene];
  float gz = (z - HM_ORIGIN_ZS[scene]) / HM_STEP_ZS[scene];
  if (gx < 0.0F) gx = 0.0F;
  if (gz < 0.0F) gz = 0.0F;
  if (gx > hw - 1.001F) gx = hw - 1.001F;
  if (gz > hd - 1.001F) gz = hd - 1.001F;
  const int ix = (int)gx;
  const int iz = (int)gz;
  const float fx = gx - ix;
  const float fz = gz - iz;
  const float t = hm[iz * hw + ix] * (1.0F - fx) +
                  hm[iz * hw + ix + 1] * fx;
  const float b = hm[(iz + 1) * hw + ix] * (1.0F - fx) +
                  hm[(iz + 1) * hw + ix + 1] * fx;
  return t * (1.0F - fz) + b * fz;
}

